-- ADC 牙科诊所：轻量牙医运营绩效结果（PostgreSQL 18）
-- 本文件不包含工资、奖金支付、成本、利润或会计分录。
-- 这是绩效表的独立示例；完整 33 表建表基线已包含同一张表，执行全量脚本后不要重复执行本文件。

CREATE TABLE "DENTIST_PERFORMANCE" (
    "performance_id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "dentist_id" BIGINT NOT NULL,
    "clinic_id" BIGINT NOT NULL,
    "period_start" DATE NOT NULL,
    "period_end" DATE NOT NULL,
    "appointment_count" INT NOT NULL DEFAULT 0,
    "attended_count" INT NOT NULL DEFAULT 0,
    "cancelled_count" INT NOT NULL DEFAULT 0,
    "no_show_count" INT NOT NULL DEFAULT 0,
    "completed_count" INT NOT NULL DEFAULT 0,
    "treatment_count" INT NOT NULL DEFAULT 0,
    "workload_target_count" INT NOT NULL DEFAULT 0,
    "performance_score" DECIMAL(8,2) NULL,
    "reward_level" VARCHAR(20) NOT NULL DEFAULT 'NONE',
    "review_status" VARCHAR(20) NOT NULL DEFAULT 'DRAFT',
    "reviewed_by_account_id" BIGINT NULL,
    "reviewed_at" TIMESTAMP WITH TIME ZONE NULL,
    "calculation_version" VARCHAR(30) NOT NULL DEFAULT 'v1',
    "calculated_at" TIMESTAMP WITH TIME ZONE NOT NULL,
    "created_at" TIMESTAMP WITH TIME ZONE NOT NULL,
    CONSTRAINT uq_dentist_performance_period
        UNIQUE ("dentist_id", "clinic_id", "period_start", "period_end", "calculation_version"),
    CONSTRAINT ck_dentist_performance_period
        CHECK ("period_start" < "period_end"),
    CONSTRAINT ck_dentist_performance_counts
        CHECK ("appointment_count" >= 0 AND "attended_count" >= 0
           AND "cancelled_count" >= 0 AND "no_show_count" >= 0
           AND "completed_count" >= 0 AND "treatment_count" >= 0),
    CONSTRAINT ck_dentist_performance_status_counts
        CHECK ("attended_count" + "cancelled_count" + "no_show_count" <= "appointment_count"
           AND "completed_count" <= "attended_count"),
    CONSTRAINT ck_dentist_performance_score
        CHECK ("workload_target_count" >= 0),
    CONSTRAINT ck_dentist_performance_score
        CHECK ("performance_score" IS NULL OR ("performance_score" >= 0 AND "performance_score" <= 100)),
    CONSTRAINT ck_dentist_performance_level
        CHECK ("reward_level" IN ('NONE', 'NORMAL', 'GOOD', 'EXCELLENT')),
    CONSTRAINT ck_dentist_performance_status
        CHECK ("review_status" IN ('DRAFT', 'CONFIRMED', 'ARCHIVED')),
    CONSTRAINT fk_dentist_performance_dentist
        FOREIGN KEY ("dentist_id") REFERENCES "DENTIST" ("dentist_id"),
    CONSTRAINT fk_dentist_performance_clinic
        FOREIGN KEY ("clinic_id") REFERENCES "CLINIC" ("clinic_id"),
    CONSTRAINT fk_dentist_performance_reviewer
        FOREIGN KEY ("reviewed_by_account_id") REFERENCES "ACCOUNT" ("account_id")
);

